function addLiquidity(uint amountA, uint amountB) external {
  if (totalSupply == 0) {
    liquidity = sqrt(amountA * amountB); // bootstrap the ratio
  } else {
    liquidity = min(
      amountA * totalSupply / reserveA,
      amountB * totalSupply / reserveB
    );
  }
  _mint(msg.sender, liquidity);
}

function swapAForB(uint amountIn) external returns (uint amountOut) {
  uint amountInWithFee = amountIn * 997 / 1000; // 0.3% fee
  uint k = reserveA * reserveB;
  uint newReserveB = k / (reserveA + amountInWithFee);
  amountOut = reserveB - newReserveB;
}
